type View = "dashboard" | "brands" | "matches" | "cases" | "notifications" | "users" | "settings";
type BrandStatus = "Activa" | "Procesando" | "Pausada" | "Con error" | "Archivada";
type MatchLevel = "Alta" | "Media" | "Baja";
type MatchStatus = "Pendiente" | "En observación" | "Descartada" | "Convertida en caso";
type CaseStage = "Evaluación" | "Preparación" | "Presentado" | "Seguimiento";

type Brand = { id: string; name: string; owner: string; registration: string; classes: string; country: string; status: BrandStatus; matches: number; cases: number; updated: string; rut: string; inapiUrl: string; visual: string };
type Match = { id: string; brandId: string; brand: string; found: string; applicant: string; application: string; score: number; level: MatchLevel; status: MatchStatus; date: string; deadline?: string; source: string; owner: string; rut: string; applicantRut: string; officialUrl: string };
type LegalCase = { id: string; title: string; brand: string; client: string; stage: CaseStage; priority: MatchLevel; deadline: string; owner: string; sourceMatch?: string };
type DemoUser = { id: string; name: string; email: string; createdAt: string; initials: string };
type Notice = { id: string; title: string; brand: string; urgency: "Alta" | "Media"; status: "Pendiente" | "Gestionada"; date: string; subject: string; body: string };
type DemoSnapshot = { brands: Brand[]; matches: Match[]; cases: LegalCase[]; users: DemoUser[]; notices: Notice[] };
type RutCandidate = { name: string; registration: string; classes: string; visual: string; inapiUrl: string; description: string };

