function useDemoStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(initialValue); const [ready, setReady] = useState(false);
  useEffect(() => { const timer = window.setTimeout(() => { try { const saved = window.localStorage.getItem(key); if (saved) setValue(JSON.parse(saved) as T); } catch { /* local fallback */ } setReady(true); }, 0); return () => window.clearTimeout(timer); }, [key]);
  useEffect(() => { if (ready) window.localStorage.setItem(key, JSON.stringify(value)); }, [key, ready, value]);
  return [value, setValue] as const;
}
function Tone({ children, tone = "neutral" }: { children: React.ReactNode; tone?: string }) { return <span className={`buho-tone tone-${tone}`}>{children}</span>; }
function EmptyState({ title, copy }: { title: string; copy: string }) { return <div className="buho-empty"><span>00</span><strong>{title}</strong><p>{copy}</p></div>; }
function formatToday() { return new Intl.DateTimeFormat("es-CL", { timeZone: "America/Santiago", weekday: "long", day: "numeric", month: "short", year: "numeric" }).format(new Date()).toUpperCase().replace(" DE ", " ").replace(" DE ", " "); }

export default function BuhoAppPage() {
  const [view, setView] = useState<View>("dashboard");
  const [brands, setBrands] = useDemoStorage("buho-demo-brands", initialBrands);
  const [matches, setMatches] = useDemoStorage("buho-demo-matches", initialMatches);
  const [cases, setCases] = useDemoStorage("buho-demo-cases", initialCases);
  const [users, setUsers] = useDemoStorage("buho-demo-users", initialUsers);
  const [notices, setNotices] = useDemoStorage("buho-demo-notices", initialNotices);
  const [brandFormOpen, setBrandFormOpen] = useState(false); const [rutDrawerOpen, setRutDrawerOpen] = useState(false); const [caseFormOpen, setCaseFormOpen] = useState(false); const [userFormOpen, setUserFormOpen] = useState(false);
  const [selectedMatch, setSelectedMatch] = useState<string | null>(null); const [selectedCase, setSelectedCase] = useState<string | null>(null); const [selectedNotice, setSelectedNotice] = useState<string | null>(null);
  const [query, setQuery] = useState(""); const [levelFilter, setLevelFilter] = useState("Todas"); const [brandFilter, setBrandFilter] = useState("Todas"); const [toast, setToast] = useState(""); const [dataMode, setDataMode] = useState<"loading" | "database" | "local">("loading");
  useEffect(() => { const syncHash = () => { const hash = window.location.hash.replace("#", "") as View; if (NAV.some((item) => item.id === hash)) setView(hash); }; syncHash(); window.addEventListener("hashchange", syncHash); return () => window.removeEventListener("hashchange", syncHash); }, []);
  useEffect(() => { let active = true; fetch("/api/demo", { cache: "no-store" }).then(async (response) => { if (!active || !response.ok) { if (active) setDataMode("local"); return; } const payload = await response.json() as { data: DemoSnapshot }; applySnapshot(payload.data); setDataMode("database"); }).catch(() => active && setDataMode("local")); return () => { active = false; }; }, []); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(""), 2800); return () => window.clearTimeout(timer); }, [toast]);
  const selectedMatchData = matches.find((match) => match.id === selectedMatch); const selectedCaseData = cases.find((item) => item.id === selectedCase); const selectedNoticeData = notices.find((item) => item.id === selectedNotice);
  const filteredMatches = useMemo(() => matches.filter((match) => (levelFilter === "Todas" || match.level === levelFilter) && `${match.brand} ${match.found} ${match.applicant} ${match.rut} ${match.applicantRut}`.toLowerCase().includes(query.toLowerCase())).sort((a, b) => b.score - a.score), [levelFilter, matches, query]);
  function applySnapshot(snapshot: DemoSnapshot) { setBrands(snapshot.brands); setMatches(snapshot.matches); setCases(snapshot.cases); setUsers(snapshot.users); setNotices(snapshot.notices); }
  function navigate(next: View) { setView(next); setQuery(""); window.history.pushState(null, "", `#${next}`); }
  async function requestAction(input: Record<string, unknown>, sync = true) { if (dataMode !== "database") return false; try { const response = await fetch("/api/demo", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(input) }); const payload = await response.json() as { data?: DemoSnapshot; message?: string }; if (!response.ok) throw new Error(payload.message || "No fue posible guardar el cambio"); if (sync && payload.data) applySnapshot(payload.data); return true; } catch (error) { setToast(error instanceof Error ? error.message : "No fue posible guardar el cambio"); return false; } }
  async function addBrand(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const data = new FormData(event.currentTarget); const input = { action: "createBrand", name: String(data.get("name")), owner: String(data.get("owner")), registration: String(data.get("registration")), classes: String(data.get("classes")), country: "Chile", description: String(data.get("description")), rut: String(data.get("rut")), inapiUrl: String(data.get("inapiUrl")), visual: String(data.get("visual")) }; if (dataMode === "database") { if (!await requestAction(input)) return; } else setBrands([{ id: `BM-${100 + brands.length}`, name: input.name, owner: input.owner, registration: input.registration, classes: input.classes, country: "Chile", status: "Procesando", matches: 0, cases: 0, updated: "Ahora", rut: input.rut, inapiUrl: input.inapiUrl, visual: input.visual }, ...brands]); setBrandFormOpen(false); setToast("Marca añadida desde la simulación INAPI"); navigate("brands"); }
  async function addRutBrands(selected: RutCandidate[]) { const slots = Math.max(0, 25 - brands.length); const allowed = selected.filter((candidate) => !brands.some((brand) => brand.name.toLowerCase() === candidate.name.toLowerCase())).slice(0, slots); if (!allowed.length) { setToast(slots ? "Estas marcas ya están en seguimiento" : "No quedan cupos en el plan Estudio"); return; } const batch = allowed.map((candidate) => ({ ...candidate, owner: "Coca-Cola de Chile S.A.", country: "Chile", rut: COCA_COLA_RUT })); if (dataMode === "database") { if (!await requestAction({ action: "bulkCreateBrands", brands: batch })) return; } else setBrands([...batch.map((candidate, index): Brand => ({ id: `BM-${200 + brands.length + index}`, name: candidate.name, owner: candidate.owner, registration: candidate.registration, classes: candidate.classes, country: candidate.country, status: "Procesando", matches: 0, cases: 0, updated: "Ahora", rut: candidate.rut, inapiUrl: candidate.inapiUrl, visual: candidate.visual })), ...brands]); setRutDrawerOpen(false); setBrandFilter("Todas"); setToast(`${allowed.length} marca${allowed.length === 1 ? "" : "s"} de Coca-Cola añadida${allowed.length === 1 ? "" : "s"} al seguimiento`); }
  async function addCase(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const data = new FormData(event.currentTarget); const input = { action: "createCase", title: String(data.get("title")), brand: String(data.get("brand")), client: String(data.get("client")), priority: String(data.get("priority")), deadline: String(data.get("deadline")), owner: String(data.get("owner")), description: String(data.get("description") || "") }; if (dataMode === "database") { if (!await requestAction(input)) return; } else setCases([{ id: `BM-${1043 + cases.length}`, title: input.title, brand: input.brand, client: input.client, stage: "Evaluación", priority: input.priority as MatchLevel, deadline: input.deadline, owner: input.owner }, ...cases]); setCaseFormOpen(false); setToast("Caso creado correctamente"); navigate("cases"); }
  async function addUser(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const data = new FormData(event.currentTarget); const name = String(data.get("name")); const email = String(data.get("email")); if (dataMode === "database") { if (!await requestAction({ action: "createUser", name, email })) return; } else setUsers([...users, { id: `US-${users.length + 1}`, name, email, createdAt: formatToday(), initials: name.split(" ").map((part) => part[0]).slice(0, 2).join("").toUpperCase() }]); setUserFormOpen(false); setToast("Usuario agregado a la organización"); }
  async function reviewMatch(status: MatchStatus) { if (!selectedMatchData) return; if (dataMode === "database") { if (!await requestAction({ action: "reviewMatch", id: selectedMatchData.id, status })) return; } else setMatches(matches.map((match) => match.id === selectedMatchData.id ? { ...match, status } : match)); setToast(status === "Convertida en caso" ? "Coincidencia convertida en caso" : `Coincidencia marcada: ${status}`); setSelectedMatch(null); }
  async function moveCase(item: LegalCase, stage: CaseStage) { if (item.stage === stage) return; if (dataMode === "database") { if (!await requestAction({ action: "moveCase", id: item.id, stage })) return; } else setCases(cases.map((current) => current.id === item.id ? { ...current, stage } : current)); setToast(`${item.id} movido a ${stage}`); }
  function updateNotice(id: string, patch: Partial<Notice>) { setNotices(notices.map((item) => item.id === id ? { ...item, ...patch } : item)); if (dataMode === "database") void requestAction({ action: "updateNotice", id, ...patch }, false); }
  async function resetData() { if (dataMode === "database") await requestAction({ action: "reset" }); else applySnapshot({ brands: initialBrands, matches: initialMatches, cases: initialCases, users: initialUsers, notices: initialNotices }); setToast("Datos de demostración restaurados"); }
  async function copyText(text: string, label: string) { try { await navigator.clipboard.writeText(text); setToast(`${label} copiado`); } catch { setToast("Selecciona el texto y cópialo manualmente"); } }
  const mainAction = view === "cases" ? () => setCaseFormOpen(true) : view === "users" ? () => setUserFormOpen(true) : () => setBrandFormOpen(true); const mainActionLabel = view === "cases" ? "Agregar caso" : view === "users" ? "Agregar usuario" : "Agregar marca";
  const pageHeadings: Record<View, [string, string]> = { dashboard: ["Buenos días, José Ignacio.", "Resumen de tu cartera y acciones prioritarias"], brands: ["Marcas en seguimiento", "Administra la cartera activa de tu organización"], matches: ["Coincidencias", "Revisa y clasifica los hallazgos de tu cartera"], cases: ["Seguimiento de casos", "Gestiona cada causa sin perder el contexto original"], notifications: ["Centro de notificaciones", "Prepara comunicaciones claras para tus clientes"], users: ["Usuarios activos", "Personas con acceso a la organización"], settings: ["Configuración", "Preferencias de la experiencia de monitoreo"] };
  return <main className="buho-app"><aside className="buho-sidebar"><Link className="buho-wordmark" href="/" aria-label="Buho Marc, volver al sitio">BUHO MARC</Link><span className={`buho-data-mode is-${dataMode}`}><i />{dataMode === "database" ? "DATOS EN RAILWAY" : dataMode === "loading" ? "CONECTANDO" : "MODO LOCAL"}</span><nav aria-label="Navegación de la aplicación">{NAV.map((item, index) => <button className={view === item.id ? "is-active" : ""} key={item.id} onClick={() => navigate(item.id)} type="button"><span>0{index + 1}</span>{item.label}{item.id === "notifications" && notices.filter((notice) => notice.status === "Pendiente").length > 0 && <b>{notices.filter((notice) => notice.status === "Pendiente").length}</b>}</button>)}</nav><div className="buho-plan"><span>PLAN ESTUDIO</span><strong>{brands.length} de 25 marcas</strong><i><b style={{ width: `${Math.min(100, brands.length / 25 * 100)}%` }} /></i><small>{Math.max(0, 25 - brands.length)} espacios disponibles</small><Link href="/#contacto">Ver pricing para incluir más</Link></div><button className="buho-profile" type="button"><span>JI</span><div><strong>José Ignacio Ibieta</strong><small>Estudio Ibieta IP</small></div></button></aside><section className="buho-workspace"><header className="buho-topbar"><div><span className="buho-overline">{formatToday()}</span><h1>{pageHeadings[view][0]}</h1><p>{pageHeadings[view][1]}</p></div><div className="buho-actions"><label className="buho-search"><span>BUSCAR</span><input aria-label="Buscar en la vista actual" onChange={(event) => setQuery(event.target.value)} placeholder="Marca, caso, RUT o cliente" value={query} /></label><button className="buho-primary" onClick={mainAction} type="button">{mainActionLabel}<span>+</span></button></div></header>{view === "dashboard" && <Dashboard brands={brands} cases={cases} matches={matches} onMatch={setSelectedMatch} onNavigate={navigate} />}{view === "brands" && <BrandsView brands={brands} filter={brandFilter} onAdd={() => setBrandFormOpen(true)} onBulk={() => setRutDrawerOpen(true)} onFilter={setBrandFilter} onOpenMatches={(name) => { navigate("matches"); window.setTimeout(() => setQuery(name), 0); }} query={query} />}{view === "matches" && <MatchesView matches={filteredMatches} level={levelFilter} onLevel={setLevelFilter} onSelect={setSelectedMatch} />}{view === "cases" && <CasesView cases={cases.filter((item) => `${item.title} ${item.brand} ${item.client}`.toLowerCase().includes(query.toLowerCase()))} onAdd={() => setCaseFormOpen(true)} onMove={moveCase} onSelect={setSelectedCase} />}{view === "notifications" && <NotificationsView notices={notices.filter((item) => `${item.title} ${item.brand}`.toLowerCase().includes(query.toLowerCase()))} onSelect={setSelectedNotice} />}{view === "users" && <UsersView users={users.filter((user) => `${user.name} ${user.email}`.toLowerCase().includes(query.toLowerCase()))} onAdd={() => setUserFormOpen(true)} />}{view === "settings" && <SettingsView dataMode={dataMode} onReset={resetData} onToast={setToast} />}</section>{brandFormOpen && <BrandForm brandsCount={brands.length} onClose={() => setBrandFormOpen(false)} onSubmit={addBrand} />}{rutDrawerOpen && <RutBrandsDrawer brands={brands} onAdd={addRutBrands} onClose={() => setRutDrawerOpen(false)} />}{caseFormOpen && <CaseForm brands={brands} onClose={() => setCaseFormOpen(false)} onSubmit={addCase} users={users} />}{userFormOpen && <UserForm onClose={() => setUserFormOpen(false)} onSubmit={addUser} />}{selectedMatchData && <MatchDrawer match={selectedMatchData} onClose={() => setSelectedMatch(null)} onReview={reviewMatch} />}{selectedCaseData && <CaseDrawer item={selectedCaseData} onClose={() => setSelectedCase(null)} onMove={(stage) => moveCase(selectedCaseData, stage)} />}{selectedNoticeData && <NoticeDrawer notice={selectedNoticeData} onChange={(patch) => updateNotice(selectedNoticeData.id, patch)} onClose={() => setSelectedNotice(null)} onCopy={copyText} />}{toast && <div className="buho-toast" role="status"><span />{toast}</div>}</main>;
}

function Dashboard({ brands, matches, cases, onMatch, onNavigate }: { brands: Brand[]; matches: Match[]; cases: LegalCase[]; onMatch: (id: string) => void; onNavigate: (view: View) => void }) { const pending = matches.filter((item) => item.status === "Pendiente"); const followUp = brands.filter((item) => item.status !== "Archivada").length; const oppositions = cases.filter((item) => item.title.toLowerCase().includes("oposición") || item.stage !== "Seguimiento").length; const deadlines = cases.filter((item) => item.title.toLowerCase().includes("oposición")).slice(0, 4); return <><button className="buho-attention" onClick={() => pending[0] && onMatch(pending[0].id)} type="button"><div><span className="buho-live" />REQUIERE TU ATENCIÓN</div><strong>{pending.filter((item) => item.level === "Alta").length} coincidencias de alta similitud esperan revisión.</strong><span>Revisar ahora <b>→</b></span></button><div className="buho-metrics"><button onClick={() => onNavigate("brands")} type="button"><span>MARCAS EN SEGUIMIENTO</span><strong>{followUp}</strong><small>{followUp} de 25 cupos utilizados</small></button><button onClick={() => onNavigate("matches")} type="button"><span>NUEVAS COINCIDENCIAS</span><strong>{pending.length}</strong><small>{pending.filter((item) => item.level === "Alta").length} de alta similitud</small></button><button onClick={() => onNavigate("cases")} type="button"><span>CASOS ACTIVOS</span><strong>{String(cases.length).padStart(2, "0")}</strong><small>{cases.filter((item) => item.stage !== "Seguimiento").length} con plazo cercano</small></button><button onClick={() => onNavigate("cases")} type="button"><span>OPOSICIONES EN CURSO</span><strong>{String(oppositions).padStart(2, "0")}</strong><small>Revisa los próximos vencimientos</small></button></div><div className="buho-dashboard-grid"><section className="buho-panel"><header><div><span className="buho-overline">BANDEJA DE REVISIÓN</span><h2>Coincidencias nuevas</h2></div><button onClick={() => onNavigate("matches")} type="button">Ver todas</button></header>{pending.slice(0, 3).map((match) => <article className="buho-match-row" key={match.id}><Tone tone={match.level.toLowerCase()}>{match.level}</Tone><button onClick={() => onMatch(match.id)} type="button"><small>MARCA MONITOREADA</small><b>{match.brand}</b></button><button onClick={() => onMatch(match.id)} type="button"><small>SIGNO ENCONTRADO</small><b>{match.found}</b></button><a href={match.officialUrl} rel="noreferrer" target="_blank">Ver en INAPI ↗</a></article>)}</section><aside className="buho-panel buho-deadlines"><header><div><span className="buho-overline">PRÓXIMOS 30 DÍAS</span><h2>Oposiciones en curso</h2></div></header>{deadlines.map((item) => <button key={item.id} onClick={() => onNavigate("cases")} type="button"><time>{item.deadline.slice(0, 2)}<small>{item.deadline.slice(3)}</small></time><div><strong>{item.title}</strong><span>{item.brand} · {item.id}</span></div></button>)}</aside></div><FullAugustCalendar cases={cases} /></>; }
function FullAugustCalendar({ cases }: { cases: LegalCase[] }) { const events = new Map<number, LegalCase[]>(); cases.forEach((item) => { if (item.deadline.endsWith("ago")) { const date = Number(item.deadline.split(" ")[0]); events.set(date, [...(events.get(date) ?? []), item]); } }); return <section className="buho-calendar buho-full-calendar"><header><div><span className="buho-overline">AGENDA LEGAL</span><h2>Agosto 2026</h2></div><span className="buho-calendar-caption">Calendario mensual</span></header><div className="buho-month-weekdays">{["Lun", "Mar", "Mié", "Jue", "Vie", "Sáb", "Dom"].map((day) => <span key={day}>{day}</span>)}</div><div className="buho-month-grid">{Array.from({ length: 42 }, (_, index) => { const date = index - 5 + 1; const current = date >= 1 && date <= 31; const shown = current ? date : date < 1 ? 31 + date : date - 31; return <article className={`${current ? "" : "is-muted"} ${date === 22 ? "is-today" : ""}`} key={index}><span>{shown}</span>{current && (events.get(date) ?? []).map((item) => <button key={item.id} type="button"><b>{item.title.replace("Oposición ", "")}</b><small>{item.id}</small></button>)}</article>; })}</div></section>; }
function BrandsView({ brands, filter, onAdd, onBulk, onFilter, onOpenMatches, query }: { brands: Brand[]; filter: string; onAdd: () => void; onBulk: () => void; onFilter: (filter: string) => void; onOpenMatches: (name: string) => void; query: string }) { const visible = brands.filter((brand) => (filter === "Todas" || brand.status === filter) && `${brand.name} ${brand.owner} ${brand.rut}`.toLowerCase().includes(query.toLowerCase())); const tabs = ["Todas", "Activa", "Procesando"]; return <><section className="buho-quota"><div><span className="buho-overline">USO DEL PLAN</span><strong>{brands.length} de 25 marcas</strong><small>{Math.max(0, 25 - brands.length)} espacios disponibles</small></div><i><b style={{ width: `${Math.min(100, brands.length / 25 * 100)}%` }} /></i><Link href="/#contacto">Ver pricing para incluir más marcas <span>↗</span></Link></section><section className="buho-table-panel"><header><div className="buho-tabs">{tabs.map((tab) => <button className={filter === tab ? "is-active" : ""} key={tab} onClick={() => onFilter(tab)} type="button">{tab === "Activa" ? "Activas" : tab === "Procesando" ? "Procesando" : tab} <b>{tab === "Todas" ? brands.length : brands.filter((item) => item.status === tab).length}</b></button>)}</div><div className="buho-table-cta"><button className="buho-secondary" onClick={onBulk} type="button">Agregar marcas según RUT</button><button className="buho-secondary" onClick={onAdd} type="button">Nueva marca</button></div></header>{visible.length ? <div className="buho-table-wrap"><table><thead><tr><th>RUT</th><th>Marca</th><th>Titular</th><th>Clases de Nica</th><th>Estado</th><th>Coincidencias</th><th>Actualización</th><th /></tr></thead><tbody>{visible.map((brand) => <tr key={brand.id}><td><span className="buho-rut">{brand.rut}</span></td><td><div className="buho-brand-cell"><span className="buho-monogram">{brand.name.slice(0, 2)}</span><div><strong>{brand.name}</strong><small>{brand.id} · Reg. {brand.registration}</small></div></div></td><td>{brand.owner}</td><td>{brand.classes}</td><td><Tone tone={brand.status === "Activa" ? "active" : brand.status === "Procesando" ? "processing" : "neutral"}>{brand.status}</Tone></td><td><button className="buho-number-link" onClick={() => onOpenMatches(brand.name)} type="button">{brand.matches}</button></td><td>{brand.updated}</td><td><a className="buho-inapi-mini" href={brand.inapiUrl || INAPI_SEARCH_URL} rel="noreferrer" target="_blank">INAPI ↗</a></td></tr>)}</tbody></table></div> : <EmptyState title="No encontramos marcas" copy="Prueba con otro RUT, estado o término de búsqueda." />}</section></>; }
function MatchesView({ matches, level, onLevel, onSelect }: { matches: Match[]; level: string; onLevel: (level: string) => void; onSelect: (id: string) => void }) { return <section className="buho-table-panel"><header><div className="buho-filter-group"><span>NIVEL</span>{["Todas", "Alta", "Media", "Baja"].map((item) => <button className={level === item ? "is-active" : ""} key={item} onClick={() => onLevel(item)} type="button">{item}</button>)}</div><div className="buho-table-actions"><button type="button">Vista guardada</button><button type="button">Exportar</button></div></header>{matches.length ? <div className="buho-table-wrap"><table><thead><tr><th>Nivel</th><th>Comparación</th><th>RUT marca</th><th>Solicitante</th><th>RUT solicitante</th><th>Estado</th><th>Plazo</th><th /></tr></thead><tbody>{matches.map((match) => <tr className="is-clickable" key={match.id} onClick={() => onSelect(match.id)}><td><Tone tone={match.level.toLowerCase()}>{match.level}</Tone></td><td><div className="buho-comparison"><span>{match.brand}</span><i>↔</i><strong>{match.found}</strong><small>{match.id} · Solicitud {match.application}</small></div></td><td><span className="buho-rut">{match.rut}</span></td><td>{match.applicant}</td><td><span className="buho-rut">{match.applicantRut}</span></td><td><Tone tone={match.status === "Pendiente" ? "processing" : match.status === "Descartada" ? "neutral" : "active"}>{match.status}</Tone></td><td>{match.deadline ?? "Sin plazo"}</td><td><a className="buho-inapi-mini" href={match.officialUrl} onClick={(event) => event.stopPropagation()} rel="noreferrer" target="_blank">Ver en INAPI ↗</a></td></tr>)}</tbody></table></div> : <EmptyState title="Sin coincidencias en esta vista" copy="Cambia el nivel o limpia la búsqueda para volver a ver resultados." />}</section>; }
function CasesView({ cases, onAdd, onMove, onSelect }: { cases: LegalCase[]; onAdd: () => void; onMove: (item: LegalCase, stage: CaseStage) => void; onSelect: (id: string) => void }) { const [mode, setMode] = useState<"board" | "list">("board"); const [dragged, setDragged] = useState<string | null>(null); function dropOn(stage: CaseStage, event: DragEvent<HTMLDivElement>) { event.preventDefault(); const item = cases.find((candidate) => candidate.id === dragged); if (item) onMove(item, stage); setDragged(null); } return <><div className="buho-board-toolbar"><div><button className={mode === "board" ? "is-active" : ""} onClick={() => setMode("board")} type="button">Tablero</button><button className={mode === "list" ? "is-active" : ""} onClick={() => setMode("list")} type="button">Lista</button></div><div><button type="button">Responsable</button><button type="button">Prioridad</button><button className="buho-secondary" onClick={onAdd} type="button">Nuevo caso</button></div></div>{mode === "list" ? <section className="buho-table-panel"><div className="buho-table-wrap"><table><thead><tr><th>Caso</th><th>Marca</th><th>Etapa</th><th>Responsable</th><th>Próximo plazo</th><th /></tr></thead><tbody>{cases.map((item) => <tr className="is-clickable" key={item.id} onClick={() => onSelect(item.id)}><td><strong>{item.title}</strong><small>{item.id}</small></td><td>{item.brand}</td><td><Tone tone="processing">{item.stage}</Tone></td><td>{item.owner}</td><td>{item.deadline}</td><td><button className="buho-row-arrow" type="button">Abrir →</button></td></tr>)}</tbody></table></div></section> : <section className="buho-kanban">{stages.map((stage) => { const items = cases.filter((item) => item.stage === stage); return <div className={`buho-kanban-column ${dragged ? "is-drop-ready" : ""}`} key={stage} onDragOver={(event) => event.preventDefault()} onDrop={(event) => dropOn(stage, event)}><header><span>{stage}</span><b>{items.length}</b></header><div>{items.map((item) => <article draggable key={item.id} onDragEnd={() => setDragged(null)} onDragStart={() => setDragged(item.id)}><button className="buho-case-main" onClick={() => onSelect(item.id)} type="button"><div><Tone tone={item.priority.toLowerCase()}>{item.priority}</Tone><small>{item.id}</small></div><h3>{item.title}</h3><p>{item.brand} · {item.client}</p><footer><span><i />{item.deadline}</span><span>{item.owner.split(" ")[0]}</span></footer></button></article>)}</div><p className="buho-drop-copy">Arrastra aquí para mover</p></div>; })}</section>}</>; }
function NotificationsView({ notices, onSelect }: { notices: Notice[]; onSelect: (id: string) => void }) { return <section className="buho-notice-layout"><div className="buho-notice-list"><header><div className="buho-tabs"><button className="is-active" type="button">Todas <b>{notices.length}</b></button><button type="button">Pendientes</button><button type="button">Gestionadas</button></div></header>{notices.map((notice) => <button key={notice.id} onClick={() => onSelect(notice.id)} type="button"><span className={`buho-notice-dot ${notice.status === "Pendiente" ? "is-new" : ""}`} /><div><span className="buho-overline">{notice.date} · {notice.brand}</span><strong>{notice.title}</strong><small>{notice.status === "Pendiente" ? "Borrador listo para revisar" : "Comunicación gestionada"}</small></div><Tone tone={notice.urgency.toLowerCase()}>{notice.urgency}</Tone><i>→</i></button>)}</div><aside className="buho-notice-preview"><span className="buho-overline">CENTRO DE CORREOS</span><h2>Comunica sin alarmar.</h2><p>Cada alerta relevante incluye un borrador editable con el contexto y el próximo paso recomendado.</p><div><span>01</span>Revisa el contexto</div><div><span>02</span>Edita el borrador</div><div><span>03</span>Copia y envía</div></aside></section>; }
function UsersView({ users, onAdd }: { users: DemoUser[]; onAdd: () => void }) { return <section className="buho-users"><header><div><span className="buho-overline">ORGANIZACIÓN</span><h2>Estudio Ibieta IP</h2></div><button className="buho-secondary" onClick={onAdd} type="button">Agregar usuario</button></header><div className="buho-user-list">{users.map((user) => <article key={user.id}><span>{user.initials}</span><div><strong>{user.name}</strong><small>{user.email}</small></div><div><small>FECHA DE CREACIÓN</small><strong>{user.createdAt}</strong></div><Tone tone="active">Activo</Tone><button type="button">···</button></article>)}</div><p className="buho-info-line"><span>i</span>En esta versión todos los usuarios tienen acceso completo a la organización.</p></section>; }
function SettingsView({ onToast, onReset, dataMode }: { onToast: (message: string) => void; onReset: () => void; dataMode: "loading" | "database" | "local" }) { const [section, setSection] = useState("Notificaciones"); const [toggles, setToggles] = useState([true, true, false]); const content: Record<string, { title: string; copy: string; rows: [string, string][] }> = { Notificaciones: { title: "Notificaciones y recordatorios", copy: "Define qué novedades llegan al equipo y cuándo.", rows: [["Alertas de alta similitud", "Crear una alerta cuando haya una coincidencia prioritaria."], ["Recordatorios de plazo", "Avisar siete días antes de un vencimiento legal."], ["Resumen semanal", "Enviar un resumen de cartera todos los lunes."]] }, Monitoreo: { title: "Reglas de monitoreo", copy: "Estas preferencias quedarán conectadas al motor cuando esté disponible.", rows: [["Vigilar nuevas solicitudes", "Preparar nuevas consultas para el motor de cruces."], ["Incluir coincidencias fonéticas", "Mostrar coincidencias que requieran revisión humana."], ["Priorizar clases compartidas", "Elevar la prioridad de las clases de Nica en común."]] }, Organización: { title: "Datos de la organización", copy: "Información que se usará en comunicaciones y reportes.", rows: [["Perfil del estudio", "Estudio Ibieta IP · administrador José Ignacio Ibieta."], ["Acceso de colaboradores", "Victor Tirreau y el equipo pueden revisar la cartera."], ["Registro de actividad", "Conservar cambios relevantes para la demo."]] }, "Plan y cupo": { title: "Plan Estudio y cupos", copy: "La demo tiene veinticinco cupos de marcas en seguimiento.", rows: [["Avisar al llegar a 20 marcas", "Mostrar un aviso preventivo antes de agotar el plan."], ["Permitir importación por RUT", "Usar el buscador de cartera de la demo."], ["Conservar marcas pausadas", "Mantener el historial aunque se pause el seguimiento."]] } }; const active = content[section]; return <section className="buho-settings"><aside>{Object.keys(content).map((item) => <button className={section === item ? "is-active" : ""} key={item} onClick={() => setSection(item)} type="button">{item}</button>)}</aside><div><span className="buho-overline">PREFERENCIAS · {dataMode === "database" ? "POSTGRESQL CONECTADO" : "ALMACENAMIENTO LOCAL"}</span><h2>{active.title}</h2><p>{active.copy}</p>{active.rows.map(([title, copy], index) => <label key={title}><div><strong>{title}</strong><small>{copy}</small></div><input aria-label={title} checked={toggles[index]} onChange={() => setToggles(toggles.map((value, itemIndex) => itemIndex === index ? !value : value))} type="checkbox" /><i /></label>)}<div className="buho-settings-actions"><button className="buho-primary" onClick={() => onToast(`${section} guardado`)} type="button">Guardar cambios</button><button className="buho-danger" onClick={onReset} type="button">Restaurar datos demo</button></div></div></section>; }
function DrawerShell({ title, eyebrow, onClose, children, wide = false }: { title: string; eyebrow: string; onClose: () => void; children: React.ReactNode; wide?: boolean }) { return <div className="buho-overlay" role="presentation" onMouseDown={(event) => { if (event.currentTarget === event.target) onClose(); }}><aside aria-label={title} aria-modal="true" className={`buho-drawer ${wide ? "is-wide" : ""}`} role="dialog"><header><div><span className="buho-overline">{eyebrow}</span><h2>{title}</h2></div><button aria-label="Cerrar" onClick={onClose} type="button">×</button></header>{children}</aside></div>; }
function BrandForm({ onClose, onSubmit, brandsCount }: { onClose: () => void; onSubmit: (event: FormEvent<HTMLFormElement>) => void; brandsCount: number }) { const [inapiUrl, setInapiUrl] = useState(""); const found = inapiUrl.trim().length > 8; const result = { name: "ACME ANDES", owner: "ACME Chile SpA", registration: "1.560.998", classes: "35, 42", rut: "77.888.410-5", visual: "ACME · denominativa", description: "Servicios comerciales, tecnológicos y de consultoría." }; return <DrawerShell eyebrow="NUEVA MARCA" onClose={onClose} title="Agregar desde INAPI"><form className="buho-form" onSubmit={onSubmit}><div className="buho-form-progress"><span className="is-current">1</span><i /><span className={found ? "is-current" : ""}>2</span><i /><span>3</span><small>Link INAPI</small><small>Resultado</small><small>Seguimiento</small></div><label>Link de la ficha INAPI<input name="inapiUrl" onChange={(event) => setInapiUrl(event.target.value)} placeholder="https://ion.inapi.cl/Marca/..." required type="url" value={inapiUrl} /></label><p className="buho-import-note">Por ahora esta consulta es una simulación: al pegar el enlace, Buho Marc carga parámetros de ejemplo.</p>{found && <article className="buho-import-result"><span className="buho-overline">FICHA ENCONTRADA · DEMO</span><div><span className="buho-visual-tile">{result.visual}</span><div><strong>{result.name}</strong><small>{result.owner} · RUT {result.rut}</small></div></div><dl><div><dt>Registro</dt><dd>{result.registration}</dd></div><div><dt>Clases de Nica</dt><dd>{result.classes}</dd></div><div><dt>Estado</dt><dd>Vigente</dd></div></dl><input name="name" type="hidden" value={result.name} /><input name="owner" type="hidden" value={result.owner} /><input name="registration" type="hidden" value={result.registration} /><input name="classes" type="hidden" value={result.classes} /><input name="rut" type="hidden" value={result.rut} /><input name="visual" type="hidden" value={result.visual} /><input name="description" type="hidden" value={result.description} /></article>}<p className="buho-capacity">Usarás el espacio {brandsCount + 1} de 25 incluido en el plan Estudio.</p><footer><button onClick={onClose} type="button">Cancelar</button><button className="buho-primary" disabled={!found} type="submit">Agregar al seguimiento <span>→</span></button></footer></form></DrawerShell>; }
function RutBrandsDrawer({ brands, onAdd, onClose }: { brands: Brand[]; onAdd: (selected: RutCandidate[]) => void; onClose: () => void }) { const [rut, setRut] = useState(""); const [searched, setSearched] = useState(false); const [selected, setSelected] = useState<string[]>([]); const slots = Math.max(0, 25 - brands.length); const toggle = (name: string) => setSelected((current) => current.includes(name) ? current.filter((item) => item !== name) : [...current, name]); const usable = cocaColaCatalogue.filter((candidate) => !brands.some((brand) => brand.name.toLowerCase() === candidate.name.toLowerCase())); return <DrawerShell eyebrow="IMPORTACIÓN DEMO" onClose={onClose} title="Agregar marcas según RUT" wide><div className="buho-drawer-scroll"><p className="buho-rut-intro">Ingresa cualquier RUT. Para esta demo se mostrará la cartera ficticia de Coca-Cola de Chile S.A. y podrás elegir qué marcas seguir.</p><div className="buho-rut-search"><input aria-label="RUT para buscar cartera" onChange={(event) => setRut(event.target.value)} placeholder="Ej. 96.671.040-3" value={rut} /><button className="buho-primary" onClick={() => setSearched(Boolean(rut.trim()))} type="button">Buscar <span>→</span></button></div>{searched && <><div className="buho-rut-result-head"><div><span className="buho-overline">TITULAR ENCONTRADO · DEMO</span><h3>Coca-Cola de Chile S.A.</h3><small>RUT {COCA_COLA_RUT} · {usable.length} marcas disponibles</small></div><span>{slots} cupos disponibles</span></div><div className="buho-rut-table"><table><thead><tr><th>Seguir</th><th>Marca</th><th>Link a INAPI</th><th>Visuales</th><th>Clases de Nica</th></tr></thead><tbody>{cocaColaCatalogue.map((candidate) => { const already = !usable.some((item) => item.name === candidate.name); const checked = selected.includes(candidate.name); return <tr key={candidate.name}><td><input aria-label={`Seguir ${candidate.name}`} checked={checked} disabled={already || (!checked && selected.length >= slots)} onChange={() => toggle(candidate.name)} type="checkbox" /></td><td><strong>{candidate.name}</strong><small>Reg. demo {candidate.registration}</small>{already && <em>Ya en seguimiento</em>}</td><td><a href={candidate.inapiUrl} rel="noreferrer" target="_blank">Ver en INAPI ↗</a></td><td><span className="buho-visual-tile">{candidate.visual}</span><small>{candidate.description}</small></td><td>{candidate.classes}</td></tr>; })}</tbody></table></div></>}</div><footer className="buho-drawer-actions"><button onClick={onClose} type="button">Cancelar</button><button className="buho-primary" disabled={!selected.length} onClick={() => onAdd(cocaColaCatalogue.filter((candidate) => selected.includes(candidate.name)))} type="button">Agregar {selected.length || ""} marca{selected.length === 1 ? "" : "s"} <span>→</span></button></footer></DrawerShell>; }
function CaseForm({ brands, users, onClose, onSubmit }: { brands: Brand[]; users: DemoUser[]; onClose: () => void; onSubmit: (event: FormEvent<HTMLFormElement>) => void }) { return <DrawerShell eyebrow="NUEVO CASO" onClose={onClose} title="Crear caso"><form className="buho-form" onSubmit={onSubmit}><label>Título del caso<input name="title" placeholder="Ej. Oposición signo similar" required /></label><label>Marca relacionada<select name="brand">{brands.map((item) => <option key={item.id}>{item.name}</option>)}</select></label><label>Cliente<input name="client" placeholder="Organización propietaria" required /></label><div className="buho-form-grid"><label>Prioridad<select defaultValue="Media" name="priority"><option>Alta</option><option>Media</option><option>Baja</option></select></label><label>Próximo plazo<input name="deadline" placeholder="Ej. 30 ago" required /></label></div><label>Responsable<select name="owner">{users.map((user) => <option key={user.id}>{user.name}</option>)}</select></label><label>Descripción<textarea name="description" placeholder="Contexto y próximos pasos" rows={5} /></label><footer><button onClick={onClose} type="button">Cancelar</button><button className="buho-primary" type="submit">Crear caso <span>→</span></button></footer></form></DrawerShell>; }
function UserForm({ onClose, onSubmit }: { onClose: () => void; onSubmit: (event: FormEvent<HTMLFormElement>) => void }) { return <DrawerShell eyebrow="ORGANIZACIÓN" onClose={onClose} title="Agregar usuario"><form className="buho-form" onSubmit={onSubmit}><label>Nombre completo<input name="name" placeholder="Nombre y apellido" required /></label><label>Correo electrónico<input name="email" placeholder="nombre@estudio.cl" required type="email" /></label><p className="buho-capacity">El usuario tendrá acceso completo a todos los módulos de esta demo.</p><footer><button onClick={onClose} type="button">Cancelar</button><button className="buho-primary" type="submit">Agregar usuario <span>→</span></button></footer></form></DrawerShell>; }
function MatchDrawer({ match, onClose, onReview }: { match: Match; onClose: () => void; onReview: (status: MatchStatus) => void }) { return <DrawerShell eyebrow={`${match.id} · ${match.source}`} onClose={onClose} title="Revisión de coincidencia" wide><div className="buho-drawer-scroll"><div className="buho-match-summary"><Tone tone={match.level.toLowerCase()}>{match.level}</Tone><strong>{match.score}%</strong><div><span>SIMILITUD TOTAL</span><small>Revisión pendiente · {match.date}</small></div><a href={match.officialUrl} rel="noreferrer" target="_blank">Ver en INAPI ↗</a></div><div className="buho-side-by-side"><article><span>MARCA MONITOREADA</span><div className="buho-mark-card">{match.brand}</div><dl><div><dt>RUT</dt><dd>{match.rut}</dd></div><div><dt>ID</dt><dd>{match.brandId}</dd></div><div><dt>Clases</dt><dd>29, 30, 35</dd></div></dl></article><i>↔</i><article><span>SIGNO ENCONTRADO</span><div className="buho-mark-card is-found">{match.found}</div><dl><div><dt>RUT</dt><dd>{match.applicantRut}</dd></div><div><dt>Solicitud</dt><dd>{match.application}</dd></div><div><dt>Solicitante</dt><dd>{match.applicant}</dd></div></dl></article></div><section className="buho-explanation"><span className="buho-overline">POR QUÉ SE DETECTÓ</span><p>El signo encontrado comparte la estructura denominativa principal y coincide en clases relacionadas. Esta explicación corresponde a datos ficticios de la demo; el motor real aún no está conectado.</p></section></div><footer className="buho-drawer-actions"><button onClick={() => onReview("Descartada")} type="button">Descartar</button><button onClick={() => onReview("En observación")} type="button">Mantener en observación</button><button className="buho-primary" onClick={() => onReview("Convertida en caso")} type="button">Convertir en caso <span>→</span></button></footer></DrawerShell>; }
function CaseDrawer({ item, onClose, onMove }: { item: LegalCase; onClose: () => void; onMove: (stage: CaseStage) => void }) { return <DrawerShell eyebrow={item.id} onClose={onClose} title={item.title}><div className="buho-drawer-scroll"><div className="buho-case-hero"><Tone tone={item.priority.toLowerCase()}>{item.priority}</Tone><Tone tone="active">{item.stage}</Tone><h3>{item.brand}</h3><p>{item.client}</p></div><section className="buho-detail-grid"><div><span>Responsable</span><strong>{item.owner}</strong></div><div><span>Próximo plazo</span><strong>{item.deadline}</strong></div><div><span>Coincidencia de origen</span><strong>{item.sourceMatch ?? "Creado manualmente"}</strong></div><div><span>Etapa</span><select aria-label="Mover caso a etapa" onChange={(event) => onMove(event.target.value as CaseStage)} value={item.stage}>{stages.map((stage) => <option key={stage}>{stage}</option>)}</select></div></section><section className="buho-case-section"><header><h3>Tareas</h3><button type="button">Agregar</button></header><label><input defaultChecked type="checkbox" />Revisar antecedentes de la publicación</label><label><input type="checkbox" />Confirmar instrucciones con cliente</label><label><input type="checkbox" />Preparar borrador de oposición</label></section><section className="buho-case-section"><header><h3>Actividad</h3></header><p><span>HOY</span>{item.owner} actualizó la prioridad del caso.</p><p><span>ANTES</span>Se vinculó la comparación original.</p></section></div><footer className="buho-drawer-actions"><button onClick={onClose} type="button">Cerrar</button>{item.stage !== "Seguimiento" && <button className="buho-primary" onClick={() => onMove(stages[stages.indexOf(item.stage) + 1])} type="button">Mover a siguiente etapa <span>→</span></button>}</footer></DrawerShell>; }
function NoticeDrawer({ notice, onClose, onChange, onCopy }: { notice: Notice; onClose: () => void; onChange: (patch: Partial<Notice>) => void; onCopy: (text: string, label: string) => void }) { return <DrawerShell eyebrow={`${notice.id} · ${notice.brand}`} onClose={onClose} title="Correo prehecho" wide><div className="buho-drawer-scroll"><div className="buho-mail-context"><Tone tone={notice.urgency.toLowerCase()}>{notice.urgency}</Tone><div><strong>{notice.title}</strong><small>Destinatario sugerido: contacto del cliente</small></div></div><label className="buho-mail-field">Asunto<div><input onChange={(event) => onChange({ subject: event.target.value })} value={notice.subject} /><button onClick={() => onCopy(notice.subject, "Asunto")} type="button">Copiar asunto</button></div></label><label className="buho-mail-field">Cuerpo del correo<textarea onChange={(event) => onChange({ body: event.target.value })} rows={16} value={notice.body} /><button onClick={() => onCopy(notice.body, "Correo")} type="button">Copiar correo</button></label><p className="buho-info-line"><span>i</span>Buho Marc no envía este correo. Puedes editarlo y copiarlo para enviarlo desde tu canal habitual.</p></div><footer className="buho-drawer-actions"><button onClick={onClose} type="button">Cerrar</button><button onClick={() => { onChange({ status: "Gestionada" }); onClose(); }} type="button">Marcar como enviado</button><button className="buho-primary" onClick={() => onCopy(notice.body, "Correo")} type="button">Copiar correo <span>→</span></button></footer></DrawerShell>; }
